{
  "name": "nodered-agents",
  "version": "1.0.0",
  "description": "Private dev workspace for the @tbrandenburg/node-red-agents package (local Node-RED runtime + demo)",
  "private": true,
  "workspaces": [
    "packages/*"
  ],
  "scripts": {
    "start": "node-red --userDir ./data",
    "dev": "nodemon --watch data/nodes --ext js,html,json --exec \"node-red --userDir ./data\"",
    "test": "npm test --workspaces --if-present"
  },
  "keywords": [],
  "author": "",
  "license": "MIT",
  "type": "commonjs",
  "engines": {
    "node": ">=22"
  },
  "devDependencies": {
    "@eslint/js": "^10.0.1",
    "eslint": "^10.14.0",
    "eslint-config-prettier": "^10.1.8",
    "eslint-plugin-n": "^18.5.0",
    "globals": "^17.14.0",
    "node-red": "^5.0.9",
    "nodemon": "^3.1.14",
    "prettier": "^3.9.10"
  },
  "overrides": {
    "ip-address": "^10.7.4",
    "js-yaml": "^4.3.1",
    "jsonata": "^2.2.2"
  }
}

{
  "name": "@tbrandenburg/node-red-agents",
  "version": "0.5.0",
  "description": "Node-RED nodes for running coding agents (opencode, pi) and GitHub CLI operations from flows.",
  "keywords": [
    "node-red",
    "agent",
    "ai-agent",
    "opencode",
    "pi",
    "coding-agent",
    "sandbox",
    "srt",
    "ai",
    "llm",
    "github",
    "gh",
    "github-cli"
  ],
  "homepage": "https://github.com/tbrandenburg/node-red-agents#readme",
  "bugs": {
    "url": "https://github.com/tbrandenburg/node-red-agents/issues"
  },
  "repository": {
    "type": "git",
    "url": "git+https://github.com/tbrandenburg/node-red-agents.git",
    "directory": "packages/node-red-agents"
  },
  "license": "MIT",
  "publishConfig": {
    "access": "public"
  },
  "files": [
    "MODELS-DEV-LICENSE",
    "nodes/**/*.js",
    "nodes/**/*.html",
    "nodes/**/icons/**",
    "nodes/**/examples/**",
    "nodes/gh/README.md",
    "shared/**/*.js",
    "!**/test/**",
    "!**/fixtures/**"
  ],
  "engines": {
    "node": ">=22"
  },
  "scripts": {
    "test": "node --test --experimental-test-coverage=false 'nodes/**/test/**/*.spec.js' 'shared/**/test/**/*.spec.js' && node --test nodes/agent/test/catalog-release.cases.js"
  },
  "node-red": {
    "version": ">=4.0.0",
    "nodes": {
      "agent": "nodes/agent/agent.js",
      "agent-server": "nodes/agent-server/agent-server.js",
      "gh": "nodes/gh/gh.js",
      "interaction": "nodes/interaction/interaction.js",
      "model-provider": "nodes/model-provider/model-provider.js",
      "model": "nodes/model/model.js",
      "decision": "nodes/decision/decision.js"
    }
  },
  "devDependencies": {
    "node-red-node-test-helper": "^0.3.6"
  },
  "dependencies": {
    "@ai-sdk/gateway": "4.0.111",
    "@openrouter/ai-sdk-provider": "3.1.0",
    "ai": "7.0.138",
    "ajv": "^8.20.0",
    "zod": "4.6.7"
  }
}
